<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<h1 class="h4 mb-3">Pengiriman</h1>
<?php if ($this->session->flashdata('success')): ?><div class="alert alert-success py-2"><?php echo html_escape($this->session->flashdata('success')); ?></div><?php endif; ?>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Pesanan</th><th>Penerima</th><th>Resi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($shipments as $shipment): ?><tr><td><?php echo html_escape($shipment->order_number); ?></td><td><?php echo html_escape($shipment->recipient_name); ?></td><td><?php echo html_escape((string)$shipment->tracking_number); ?></td><td><?php echo html_escape($shipment->status); ?></td><td><form method="post" action="<?php echo site_url('admin/shipments/update_status/'.$shipment->id); ?>" class="d-flex gap-2"><input type="hidden" name="<?php echo $this->security->get_csrf_token_name(); ?>" value="<?php echo $this->security->get_csrf_hash(); ?>"><input class="form-control form-control-sm" name="tracking_number" value="<?php echo html_escape((string)$shipment->tracking_number); ?>" placeholder="Nomor resi"><select class="form-select form-select-sm" name="status"><?php foreach (array('pending','processing','packed','shipped','delivered','cancelled') as $status): ?><option value="<?php echo $status; ?>" <?php echo $shipment->status === $status?'selected':''; ?>><?php echo ucfirst($status); ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-primary" type="submit">Simpan</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
